"use strict";
import { createContext, useContext, useState } from "react";
export const ModifyLockContext = createContext(null);
export const ModifyLockProvider = ({ children }) => {
  const [activeOption, setActiveOption] = useState("Increase");
  return <ModifyLockContext.Provider value={{ setActiveOption, activeOption }}>{children}</ModifyLockContext.Provider>;
};
export const useModifyLockContext = () => {
  const context = useContext(ModifyLockContext);
  if (!context) {
    throw new Error("useModifyLock must be used within a ModifyLockProvider");
  }
  return context;
};
