"use strict";
import { Flex } from "ui/src";
export default function StatusCard({
  status = "warning",
  icon,
  content
}) {
  const variants = {
    critical: {
      background: "$statusCritical2",
      color: "$statusCritical"
    },
    warning: {
      background: "$statusWarning2",
      color: "$statusWarning"
    },
    success: {
      background: "$statusSuccess2",
      color: "$statusSuccess"
    }
  };
  return <Flex
    row
    gap={"$spacing16"}
    backgroundColor={variants[status].background}
    p={"$spacing20"}
    $md={{ p: "$spacing16" }}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={variants[status].background}
  >
      <Flex height={50} width={50} backgroundColor={variants[status].background} centered borderRadius={"$roundedFull"}>
        {icon}
      </Flex>
      <Flex flex={1}>{content}</Flex>
    </Flex>;
}
